//! Generated by `tools/gen_fused_attn.py` from `device/rpa/prefill_kvd256.rs` (`ragged_prefill_pair_kvd256`, `ragged_prefill_pair_kvd256_r16`) and `device/dattn/sliding.rs`
//! (`sliding_decode_view_impl!` for 16 decode rows): the same code, with the operands the fused sliding-layer kernel carves out of its blobs taken as views.
//! Do not edit by hand.

mod prefill {
use furiosa_opt_std::prelude::*;

use crate::Chip;
use crate::axes::*;

type Cl = m![Pw];
type HeadKb = m![Ns, Ts % 32];
type HeadX = m![Ns, Dummy32];
type HeadOne = m![Ns, 1 # 32];


pub(crate) fn prefill_wave0(
    device: &mut Device,
    q: HbmTensorView<'_, bf16, Chip, impl M>,
    k_cache: &HbmTensor<bf16, Chip, m![Rf, Ns, Ds]>,
    v_cache: &HbmTensor<bf16, Chip, m![Rf, Ns, Ds]>,
    win_index: &HbmTensor<i32, Chip, m![Pw, Kw5]>,
    mask: HbmTensorView<'_, bf16, Chip, impl M>,
    pen: HbmTensorView<'_, bf16, Chip, impl M>,
    out: HbmTensorViewMut<'_, bf16, Chip, impl M>,
) {
    // ---- q all-gather over the 32 key-block slices of each head ----
    let q_shard: DmTensor<bf16, Chip, Cl, m![Ns, Tc % 32], m![Tc / 32, Gs, Ds]> = q.to_dm(&mut device.tdma);
    let q_all: DmTensor<bf16, Chip, Cl, HeadX, m![Tc / 32, Gs, Ds / 16, Tc % 32, Ds % 16]> = device
        .main
        .begin(q_shard.view())
        .fetch::<m![Tc / 32, Gs, Ds / 16], m![Ds % 16]>()
        .switch::<HeadX, m![Tc / 32, Gs, Ds / 16, Tc % 32]>(SwitchConfig::Broadcast1 { slice1: 32, slice0: 1 })
        .collect::<m![Tc / 32, Gs, Ds / 16, Tc % 32], m![Ds % 16]>()
        .commit_trim::<m![Ds % 16]>()
        .commit();
    let q_all: DmTensor<bf16, Chip, Cl, HeadKb, m![Tc / 32, Gs, Ds / 16, Tc % 32, Ds % 16]> = unsafe { q_all.reshape() };

    // ---- key slots: ONE window gather (ring + chunk keys), zero filled beyond the 36 slots ----
    let mut k_both: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk, Ds]> = DmTensor::new();
    k_both.view_mut().memset(const { bf16::from_f32(0.0) }, &mut device.sub);
    let k_win: DmTensor<bf16, Chip, Cl, m![Ns, Kw5 % 32], m![Kw5 / 32, Ds]> = k_cache.dma_gather_scaled(win_index);
    let k_win: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk = 40, Ds]> = unsafe { k_win.reshape() };
    device
        .main
        .begin(k_win.view())
        .fetch::<m![Kk = 40, Ds / 16], m![Ds % 16]>()
        .collect::<m![Kk = 40, Ds / 16], m![Ds % 16]>()
        .commit_trim::<m![Ds % 16]>()
        .commit_view(k_both.view_mut().tile::<m![Kk], 40, m![Kk = 40 #{!} 64, Ds]>(0));
    let k_trf: TrfTensor<bf16, Chip, Cl, HeadKb, m![Kk % 8], m![Kk / 8, Ds]> = device
        .sub
        .begin(k_both.view())
        .fetch::<m![Kk % 8, Kk / 8, Ds / 16], m![Ds % 16]>()
        .collect::<m![Kk % 8, Kk / 8, Ds / 16], m![Ds % 16]>()
        .to_trf();

    // ---- per-key additive penalty [Kk] ----
    let pen_dm: DmTensor<bf16, Chip, Cl, HeadKb, m![Seg, Ts / 32]> = pen.to_dm(&mut device.tdma);
    let pen_kk: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk]> = unsafe { pen_dm.reshape() };
    let pen_vrf: VrfTensor<f32, Chip, Cl, HeadKb, m![Kk]> = device
        .sub
        .begin(pen_kk.view())
        .fetch::<m![1], m![Kk]>()
        .fetch_cast::<f32>()
        .collect::<m![Kk / 8], m![Kk % 8]>()
        .to_vrf();

    // ---- scores S[Gs, Tc, Kk] (bf16), penalty added in the VE ----
    let s: DmTensor<bf16, Chip, Cl, HeadKb, m![Gs, Tc, Kk]> = device
        .main
        .begin(q_all.view())
        .fetch::<m![Gs, Tc / 32, Tc % 32, Ds / 16], m![Ds % 16]>()
        .collect::<m![Gs, Tc / 32, Tc % 32, Ds / 16], m![Ds % 16]>()
        .contract_outer::<m![Gs, Tc, Ds / 32, Kk / 8], m![Ds % 32], _, _, _>(&k_trf)
        .contract_packet::<m![1]>()
        .contract_time::<m![Gs, Tc, Kk / 8]>()
        .contract_lane::<m![Gs, Tc, Kk / 8], m![Kk % 8]>(LaneMode::Interleaved)
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_clip(ClipBinaryOpF32::Add, &pen_vrf)
        .vector_final()
        .cast::<bf16, m![Kk % 8 # 16]>()
        .commit_trim::<m![Kk % 8]>()
        .commit();

    // ---- row max over the key slots (penalised ones are far below; all-reduce Max over the head's 32 key-block slices) ----
    let m_dm: DmTensor<f32, Chip, Cl, HeadX, m![Gs, Tc]> = device
        .main
        .begin(s.view())
        .fetch::<m![Gs, Tc, Kk / 16], m![Kk % 16]>()
        .fetch_cast::<f32>()
        .collect::<m![Gs, Tc, Kk / 8], m![Kk % 8]>()
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_split::<m![Gs, Tc, Kk / 4], m![Kk % 4]>()
        .vector_intra_slice_reduce::<Kk, m![Gs, Tc], m![1 # 4]>(IntraSliceReduceOpF32::Max)
        .vector_widen_pad::<m![1 # 8]>()
        .vector_inter_slice_reduce::<HeadX, m![Gs, Tc]>(InterSliceReduceOpF32::Max)
        .vector_final()
        .transpose::<m![Gs, Tc / 2], m![Tc % 2 # 8]>()
        .commit_trim::<m![Tc % 2]>()
        .commit();
    let m_dm: DmTensor<f32, Chip, Cl, HeadKb, m![Gs, Tc]> = unsafe { m_dm.reshape() };

    // ---- masks: [Tc, Seg, 32 slots] per slice (host builds the zero padding of the chunk part) ----
    let mask_dm: DmTensor<bf16, Chip, Cl, HeadKb, m![Tc, Seg, Ts / 32]> = mask.to_dm(&mut device.tdma);
    let mask_both: DmTensor<bf16, Chip, Cl, HeadKb, m![Tc, Kk]> = unsafe { mask_dm.reshape() };

    // ---- p = bf16(min(exp(s - max), mask)), in tiles of 16 query rows (VRF holds one mask tile) ----
    let mut p: DmTensor<bf16, Chip, Cl, HeadKb, m![Gs, Tc, Kk]> = DmTensor::new();
    // The 4 tiles are expanded by hand (all tiles visible to the scheduler). Do NOT use `#[unroll]` here: it makes the compiler drop the whole decode attention of the N3 kernel
    // (`sliding_ragged_s2_b8_h`: the decode store goes through a tile of the same output handle), i.e. wrong decode rows.
    const _: () = assert!(Tc::SIZE == 64);
    macro_rules! p_tile {
        ($i:expr) => {{
        let i: usize = $i;
        let mask_tile = mask_both.view().tile::<m![Tc], 16, m![Tc = 16 # 64, Kk]>(16 * i);
        let mask_vrf: VrfTensor<f32, Chip, Cl, HeadKb, m![Tc = 16, Kk]> = device
            .sub
            .begin(mask_tile)
            .fetch::<m![1], m![Tc = 16, Kk]>()
            .fetch_cast::<f32>()
            .collect::<m![Tc = 16, Kk / 8], m![Kk % 8]>()
            .to_vrf();
        let m_tile = m_dm.view().tile::<m![Tc], 16, m![Gs, Tc = 16 # 64]>(16 * i);
        let m_vrf: VrfTensor<f32, Chip, Cl, HeadKb, m![Gs, Tc = 16]> = device
            .sub
            .begin(m_tile)
            .fetch::<m![Gs], m![Tc = 16]>()
            .collect::<m![Gs, Tc = 16 / 8], m![Tc = 16 % 8]>()
            .to_vrf();
        let s_tile = s.view().tile::<m![Tc], 16, m![Gs, Tc = 16 # 64, Kk]>(16 * i);
        device
            .main
            .begin(s_tile)
            .fetch::<m![Gs], m![Tc = 16, Kk]>()
            .fetch_cast::<f32>()
            .collect::<m![Gs, Tc = 16, Kk / 8], m![Kk % 8]>()
            .vector_init()
            .vector_intra_slice_tag(TagMode::Zero)
            .vector_narrow_split::<m![Gs, Tc = 16, Kk / 4], m![Kk % 4]>()
            .vector_fp_binary(FpBinaryOp::SubF, &m_vrf)
            .vector_fp_unary(FpUnaryOp::Exp)
            .vector_widen_concat::<m![Gs, Tc = 16, Kk / 8], m![Kk % 8]>()
            .vector_clip(ClipBinaryOpF32::Min, &mask_vrf)
            .vector_final()
            .cast::<bf16, m![Kk % 8 # 16]>()
            .commit_trim::<m![Kk % 8]>()
            .commit_view(p.view_mut().tile::<m![Tc], 16, m![Gs, Tc = 16 #{!} 64, Kk]>(16 * i));
        }};
    }
    p_tile!(0);
    p_tile!(1);
    p_tile!(2);
    p_tile!(3);

    // ---- row sum of the (bf16) weights, all-reduced; EPS added once in total ----
    let l_dm: DmTensor<f32, Chip, Cl, HeadX, m![Gs, Tc]> = device
        .main
        .begin(p.view())
        .fetch::<m![Gs, Tc, Kk / 16], m![Kk % 16]>()
        .fetch_cast::<f32>()
        .collect::<m![Gs, Tc, Kk / 8], m![Kk % 8]>()
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_split::<m![Gs, Tc, Kk / 4], m![Kk % 4]>()
        .vector_intra_slice_reduce::<Kk, m![Gs, Tc], m![1 # 4]>(IntraSliceReduceOpF32::Add)
        .vector_widen_pad::<m![1 # 8]>()
        .vector_clip(ClipBinaryOpF32::Add, crate::SOFTMAX_EPS / 32.0)
        .vector_inter_slice_reduce::<HeadX, m![Gs, Tc]>(InterSliceReduceOpF32::Add)
        .vector_final()
        .transpose::<m![Gs, Tc / 2], m![Tc % 2 # 8]>()
        .commit_trim::<m![Tc % 2]>()
        .commit();
    let l_dm: DmTensor<f32, Chip, Cl, HeadOne, m![Gs, Tc]> = unsafe { l_dm.reshape() };
    let l_vrf: VrfTensor<f32, Chip, Cl, HeadOne, m![Gs, Tc]> = device
        .sub
        .begin(l_dm.view())
        .fetch::<m![Gs, Tc / 8], m![Tc % 8]>()
        .collect::<m![Gs, Tc / 8], m![Tc % 8]>()
        .to_vrf();

    // ---- PV over both segments (Seg is a reduced time axis) ----
    let mut v_both: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk, Ds]> = DmTensor::new();
    v_both.view_mut().memset(const { bf16::from_f32(0.0) }, &mut device.sub);
    let v_win: DmTensor<bf16, Chip, Cl, m![Ns, Kw5 % 32], m![Kw5 / 32, Ds]> = v_cache.dma_gather_scaled(win_index);
    let v_win: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk = 40, Ds]> = unsafe { v_win.reshape() };
    device
        .main
        .begin(v_win.view())
        .fetch::<m![Kk = 40, Ds / 16], m![Ds % 16]>()
        .collect::<m![Kk = 40, Ds / 16], m![Ds % 16]>()
        .commit_trim::<m![Ds % 16]>()
        .commit_view(v_both.view_mut().tile::<m![Kk], 40, m![Kk = 40 #{!} 64, Ds]>(0));
    let v_t: DmTensor<bf16, Chip, Cl, HeadKb, m![Ds, Kk]> = device
        .main
        .begin(v_both.view())
        .fetch::<m![Ds / 8, Kk], m![Ds % 8 # 16]>()
        .collect::<m![Ds / 8, Kk], m![Ds % 8 # 16]>()
        .transpose::<m![Ds / 8, Kk / 4, Ds % 8], m![Kk % 4 # 16]>()
        .commit_trim::<m![Kk % 4]>()
        .commit();
    let v_trf: TrfTensor<bf16, Chip, Cl, HeadKb, m![Ds % 8], m![Ds / 8, Kk]> = device
        .sub
        .begin(v_t.view())
        .fetch::<m![Ds % 8, Ds / 8, Kk / 16], m![Kk % 16]>()
        .collect::<m![Ds % 8, Ds / 8, Kk / 16], m![Kk % 16]>()
        .to_trf();
    let o: DmTensor<bf16, Chip, Cl, HeadOne, m![Gs, Tc, Ds]> = device
        .main
        .begin(p.view())
        .fetch::<m![Gs, Tc, Kk / 16], m![Kk % 16]>()
        .collect::<m![Gs, Tc, Kk / 16], m![Kk % 16]>()
        .contract_outer::<m![Gs, Tc, Kk / 32, Ds / 8], m![Kk % 32], _, _, _>(&v_trf)
        .contract_packet::<m![1]>()
        .contract_time::<m![Gs, Tc, Ds / 8]>()
        .contract_lane::<m![Gs, Tc, Ds / 8], m![Ds % 8]>(LaneMode::Interleaved)
        .vector_init()
        .vector_inter_slice_reduce::<HeadOne, m![Gs, Tc, Ds / 8]>(InterSliceReduceOpF32::Add)
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_split::<m![Gs, Tc, Ds / 4], m![Ds % 4]>()
        .vector_fp_div(&l_vrf)
        .vector_widen_concat::<m![Gs, Tc, Ds / 8], m![Ds % 8]>()
        .vector_final()
        .cast::<bf16, m![Ds % 8 # 16]>()
        .commit_trim::<m![Ds % 8]>()
        .commit();

    let ov: DmTensorView<'_, bf16, Chip, Cl, HeadOne, m![Gs, Rg4, Bd16, Ds]> = unsafe { o.view().reshape() };
    ov.to_hbm_view(&mut device.tdma, out);
}

pub(crate) fn prefill_wave1_r16(
    device: &mut Device,
    q: HbmTensorView<'_, bf16, Chip, impl M>,
    k_cache: &HbmTensor<bf16, Chip, m![Rf, Ns, Ds]>,
    v_cache: &HbmTensor<bf16, Chip, m![Rf, Ns, Ds]>,
    win_index: &HbmTensor<i32, Chip, m![Pw, Kw5]>,
    mask: HbmTensorView<'_, bf16, Chip, impl M>,
    pen: HbmTensorView<'_, bf16, Chip, impl M>,
    out: HbmTensorViewMut<'_, bf16, Chip, impl M>,
) {
    // ---- q all-gather over the 32 key-block slices of each head ----
    let q_shard: DmTensor<bf16, Chip, Cl, m![Ns, Tc % 32], m![Tc / 32, Gs, Ds]> = q.to_dm(&mut device.tdma);
    let q_all: DmTensor<bf16, Chip, Cl, HeadX, m![Tc / 32, Gs, Ds / 16, Tc % 32, Ds % 16]> = device
        .main
        .begin(q_shard.view())
        .fetch::<m![Tc / 32, Gs, Ds / 16], m![Ds % 16]>()
        .switch::<HeadX, m![Tc / 32, Gs, Ds / 16, Tc % 32]>(SwitchConfig::Broadcast1 { slice1: 32, slice0: 1 })
        .collect::<m![Tc / 32, Gs, Ds / 16, Tc % 32], m![Ds % 16]>()
        .commit_trim::<m![Ds % 16]>()
        .commit();
    let q_all: DmTensor<bf16, Chip, Cl, HeadKb, m![Tc / 32, Gs, Ds / 16, Tc % 32, Ds % 16]> = unsafe { q_all.reshape() };

    // ---- key slots: ONE window gather (ring + chunk keys), zero filled beyond the 36 slots ----
    let mut k_both: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk, Ds]> = DmTensor::new();
    k_both.view_mut().memset(const { bf16::from_f32(0.0) }, &mut device.sub);
    let k_win: DmTensor<bf16, Chip, Cl, m![Ns, Kw5 % 32], m![Kw5 / 32, Ds]> = k_cache.dma_gather_scaled(win_index);
    let k_win: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk = 40, Ds]> = unsafe { k_win.reshape() };
    device
        .main
        .begin(k_win.view())
        .fetch::<m![Kk = 40, Ds / 16], m![Ds % 16]>()
        .collect::<m![Kk = 40, Ds / 16], m![Ds % 16]>()
        .commit_trim::<m![Ds % 16]>()
        .commit_view(k_both.view_mut().tile::<m![Kk], 40, m![Kk = 40 #{!} 64, Ds]>(0));
    let k_trf: TrfTensor<bf16, Chip, Cl, HeadKb, m![Kk % 8], m![Kk / 8, Ds]> = device
        .sub
        .begin(k_both.view())
        .fetch::<m![Kk % 8, Kk / 8, Ds / 16], m![Ds % 16]>()
        .collect::<m![Kk % 8, Kk / 8, Ds / 16], m![Ds % 16]>()
        .to_trf();

    // ---- per-key additive penalty [Kk] ----
    let pen_dm: DmTensor<bf16, Chip, Cl, HeadKb, m![Seg, Ts / 32]> = pen.to_dm(&mut device.tdma);
    let pen_kk: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk]> = unsafe { pen_dm.reshape() };
    let pen_vrf: VrfTensor<f32, Chip, Cl, HeadKb, m![Kk]> = device
        .sub
        .begin(pen_kk.view())
        .fetch::<m![1], m![Kk]>()
        .fetch_cast::<f32>()
        .collect::<m![Kk / 8], m![Kk % 8]>()
        .to_vrf();

    // ---- scores S[Gs, Tc, Kk] (bf16), penalty added in the VE ----
    let s: DmTensor<bf16, Chip, Cl, HeadKb, m![Gs, Tc, Kk]> = device
        .main
        .begin(q_all.view())
        .fetch::<m![Gs, Tc / 32, Tc % 32, Ds / 16], m![Ds % 16]>()
        .collect::<m![Gs, Tc / 32, Tc % 32, Ds / 16], m![Ds % 16]>()
        .contract_outer::<m![Gs, Tc, Ds / 32, Kk / 8], m![Ds % 32], _, _, _>(&k_trf)
        .contract_packet::<m![1]>()
        .contract_time::<m![Gs, Tc, Kk / 8]>()
        .contract_lane::<m![Gs, Tc, Kk / 8], m![Kk % 8]>(LaneMode::Interleaved)
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_clip(ClipBinaryOpF32::Add, &pen_vrf)
        .vector_final()
        .cast::<bf16, m![Kk % 8 # 16]>()
        .commit_trim::<m![Kk % 8]>()
        .commit();

    // ---- row max over the key slots (penalised ones are far below; all-reduce Max over the head's 32 key-block slices) ----
    let m_dm: DmTensor<f32, Chip, Cl, HeadX, m![Gs, Tc]> = device
        .main
        .begin(s.view())
        .fetch::<m![Gs, Tc, Kk / 16], m![Kk % 16]>()
        .fetch_cast::<f32>()
        .collect::<m![Gs, Tc, Kk / 8], m![Kk % 8]>()
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_split::<m![Gs, Tc, Kk / 4], m![Kk % 4]>()
        .vector_intra_slice_reduce::<Kk, m![Gs, Tc], m![1 # 4]>(IntraSliceReduceOpF32::Max)
        .vector_widen_pad::<m![1 # 8]>()
        .vector_inter_slice_reduce::<HeadX, m![Gs, Tc]>(InterSliceReduceOpF32::Max)
        .vector_final()
        .transpose::<m![Gs, Tc / 2], m![Tc % 2 # 8]>()
        .commit_trim::<m![Tc % 2]>()
        .commit();
    let m_dm: DmTensor<f32, Chip, Cl, HeadKb, m![Gs, Tc]> = unsafe { m_dm.reshape() };

    // ---- masks: [Tc, Seg, 32 slots] per slice (host builds the zero padding of the chunk part) ----
    let mask_dm: DmTensor<bf16, Chip, Cl, HeadKb, m![Tc, Seg, Ts / 32]> = mask.to_dm(&mut device.tdma);
    let mask_both: DmTensor<bf16, Chip, Cl, HeadKb, m![Tc, Kk]> = unsafe { mask_dm.reshape() };

    // ---- p = bf16(min(exp(s - max), mask)), in tiles of 16 query rows (VRF holds one mask tile) ----
    let mut p: DmTensor<bf16, Chip, Cl, HeadKb, m![Gs, Tc, Kk]> = DmTensor::new();
    // The 4 tiles are expanded by hand (all tiles visible to the scheduler). Do NOT use `#[unroll]` here: it makes the compiler drop the whole decode attention of the N3 kernel
    // (`sliding_ragged_s2_b8_h`: the decode store goes through a tile of the same output handle), i.e. wrong decode rows.
    const _: () = assert!(Tc::SIZE == 64);
    macro_rules! p_tile {
        ($i:expr) => {{
        let i: usize = $i;
        let mask_tile = mask_both.view().tile::<m![Tc], 16, m![Tc = 16 # 64, Kk]>(16 * i);
        let mask_vrf: VrfTensor<f32, Chip, Cl, HeadKb, m![Tc = 16, Kk]> = device
            .sub
            .begin(mask_tile)
            .fetch::<m![1], m![Tc = 16, Kk]>()
            .fetch_cast::<f32>()
            .collect::<m![Tc = 16, Kk / 8], m![Kk % 8]>()
            .to_vrf();
        let m_tile = m_dm.view().tile::<m![Tc], 16, m![Gs, Tc = 16 # 64]>(16 * i);
        let m_vrf: VrfTensor<f32, Chip, Cl, HeadKb, m![Gs, Tc = 16]> = device
            .sub
            .begin(m_tile)
            .fetch::<m![Gs], m![Tc = 16]>()
            .collect::<m![Gs, Tc = 16 / 8], m![Tc = 16 % 8]>()
            .to_vrf();
        let s_tile = s.view().tile::<m![Tc], 16, m![Gs, Tc = 16 # 64, Kk]>(16 * i);
        device
            .main
            .begin(s_tile)
            .fetch::<m![Gs], m![Tc = 16, Kk]>()
            .fetch_cast::<f32>()
            .collect::<m![Gs, Tc = 16, Kk / 8], m![Kk % 8]>()
            .vector_init()
            .vector_intra_slice_tag(TagMode::Zero)
            .vector_narrow_split::<m![Gs, Tc = 16, Kk / 4], m![Kk % 4]>()
            .vector_fp_binary(FpBinaryOp::SubF, &m_vrf)
            .vector_fp_unary(FpUnaryOp::Exp)
            .vector_widen_concat::<m![Gs, Tc = 16, Kk / 8], m![Kk % 8]>()
            .vector_clip(ClipBinaryOpF32::Min, &mask_vrf)
            .vector_final()
            .cast::<bf16, m![Kk % 8 # 16]>()
            .commit_trim::<m![Kk % 8]>()
            .commit_view(p.view_mut().tile::<m![Tc], 16, m![Gs, Tc = 16 #{!} 64, Kk]>(16 * i));
        }};
    }
    p_tile!(0);
    p_tile!(1);
    p_tile!(2);
    p_tile!(3);

    // ---- row sum of the (bf16) weights, all-reduced; EPS added once in total ----
    let l_dm: DmTensor<f32, Chip, Cl, HeadX, m![Gs, Tc]> = device
        .main
        .begin(p.view())
        .fetch::<m![Gs, Tc, Kk / 16], m![Kk % 16]>()
        .fetch_cast::<f32>()
        .collect::<m![Gs, Tc, Kk / 8], m![Kk % 8]>()
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_split::<m![Gs, Tc, Kk / 4], m![Kk % 4]>()
        .vector_intra_slice_reduce::<Kk, m![Gs, Tc], m![1 # 4]>(IntraSliceReduceOpF32::Add)
        .vector_widen_pad::<m![1 # 8]>()
        .vector_clip(ClipBinaryOpF32::Add, crate::SOFTMAX_EPS / 32.0)
        .vector_inter_slice_reduce::<HeadX, m![Gs, Tc]>(InterSliceReduceOpF32::Add)
        .vector_final()
        .transpose::<m![Gs, Tc / 2], m![Tc % 2 # 8]>()
        .commit_trim::<m![Tc % 2]>()
        .commit();
    let l_dm: DmTensor<f32, Chip, Cl, HeadOne, m![Gs, Tc]> = unsafe { l_dm.reshape() };
    let l_vrf: VrfTensor<f32, Chip, Cl, HeadOne, m![Gs, Tc]> = device
        .sub
        .begin(l_dm.view())
        .fetch::<m![Gs, Tc / 8], m![Tc % 8]>()
        .collect::<m![Gs, Tc / 8], m![Tc % 8]>()
        .to_vrf();

    // ---- PV over both segments (Seg is a reduced time axis) ----
    let mut v_both: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk, Ds]> = DmTensor::new();
    v_both.view_mut().memset(const { bf16::from_f32(0.0) }, &mut device.sub);
    let v_win: DmTensor<bf16, Chip, Cl, m![Ns, Kw5 % 32], m![Kw5 / 32, Ds]> = v_cache.dma_gather_scaled(win_index);
    let v_win: DmTensor<bf16, Chip, Cl, HeadKb, m![Kk = 40, Ds]> = unsafe { v_win.reshape() };
    device
        .main
        .begin(v_win.view())
        .fetch::<m![Kk = 40, Ds / 16], m![Ds % 16]>()
        .collect::<m![Kk = 40, Ds / 16], m![Ds % 16]>()
        .commit_trim::<m![Ds % 16]>()
        .commit_view(v_both.view_mut().tile::<m![Kk], 40, m![Kk = 40 #{!} 64, Ds]>(0));
    let v_t: DmTensor<bf16, Chip, Cl, HeadKb, m![Ds, Kk]> = device
        .main
        .begin(v_both.view())
        .fetch::<m![Ds / 8, Kk], m![Ds % 8 # 16]>()
        .collect::<m![Ds / 8, Kk], m![Ds % 8 # 16]>()
        .transpose::<m![Ds / 8, Kk / 4, Ds % 8], m![Kk % 4 # 16]>()
        .commit_trim::<m![Kk % 4]>()
        .commit();
    let v_trf: TrfTensor<bf16, Chip, Cl, HeadKb, m![Ds % 8], m![Ds / 8, Kk]> = device
        .sub
        .begin(v_t.view())
        .fetch::<m![Ds % 8, Ds / 8, Kk / 16], m![Kk % 16]>()
        .collect::<m![Ds % 8, Ds / 8, Kk / 16], m![Kk % 16]>()
        .to_trf();
    let o: DmTensor<bf16, Chip, Cl, HeadOne, m![Gs, Tc, Ds]> = device
        .main
        .begin(p.view())
        .fetch::<m![Gs, Tc, Kk / 16], m![Kk % 16]>()
        .collect::<m![Gs, Tc, Kk / 16], m![Kk % 16]>()
        .contract_outer::<m![Gs, Tc, Kk / 32, Ds / 8], m![Kk % 32], _, _, _>(&v_trf)
        .contract_packet::<m![1]>()
        .contract_time::<m![Gs, Tc, Ds / 8]>()
        .contract_lane::<m![Gs, Tc, Ds / 8], m![Ds % 8]>(LaneMode::Interleaved)
        .vector_init()
        .vector_inter_slice_reduce::<HeadOne, m![Gs, Tc, Ds / 8]>(InterSliceReduceOpF32::Add)
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_split::<m![Gs, Tc, Ds / 4], m![Ds % 4]>()
        .vector_fp_div(&l_vrf)
        .vector_widen_concat::<m![Gs, Tc, Ds / 8], m![Ds % 8]>()
        .vector_final()
        .cast::<bf16, m![Ds % 8 # 16]>()
        .commit_trim::<m![Ds % 8]>()
        .commit();

    let ov: DmTensorView<'_, bf16, Chip, Cl, HeadOne, m![Gs, Rg4, Bd16, Ds]> = unsafe { o.view().reshape() };
    ov.to_hbm_view(&mut device.tdma, out);
}

}

mod decode {
use furiosa_opt_std::prelude::*;

use crate::Chip;
use crate::axes::*;

/// 256 slices per cluster = 8 KV heads x 32 key lanes (ring row t lives in lane t % 32, slot t / 32).
pub(crate) type HKb = m![Ns, Tx % 32];
/// Row statistics after an all-reduce over the 32 key lanes of a head (fresh broadcast axis).
pub(crate) type HX = m![Ns, Dm32];
/// After an inter-slice Add reduce the result lives in key lane 0 of each head.
pub(crate) type HOne = m![Ns, 1 # 32];


pub(crate) fn decode_attend16(
    device: &mut Device,
    q: HbmTensorView<'_, bf16, Chip, impl M>,
    k_cache: &HbmTensor<bf16, Chip, m![Rf, Ns, Ds]>,
    v_cache: &HbmTensor<bf16, Chip, m![Rf, Ns, Ds]>,
    index: &HbmTensor<i32, Chip, m![Bd16, Tx]>,
    mask: HbmTensorView<'_, bf16, Chip, impl M>,
    dst: HbmTensorViewMut<'_, bf16, Chip, impl M>,
) {
    type Cl = m![Bd16 % 2];

    // ---- q: each slice loads a (128 / 256 B) piece of the q rows of its head, all-gathered over the 32 key lanes of the head by the
    //      switch, then into the TRF (lane = query group) ----
    let q_sh: DmTensor<bf16, Chip, Cl, m![Ns, Bd16 / 2, Gs, Ds / 128], m![Ds % 128]> = q.to_dm(&mut device.tdma);
    let q_dm: DmTensor<bf16, Chip, Cl, HX, m![Ds / 16 % 8, Bd16 / 2, Gs, Ds / 128, Ds % 16]> = device
        .main
        .begin(q_sh.view())
        .fetch::<m![Ds / 16 % 8], m![Ds % 16]>()
        .switch::<HX, m![Ds / 16 % 8, Bd16 / 2, Gs, Ds / 128]>(SwitchConfig::Broadcast1 { slice1: 32, slice0: 1 })
        .collect::<m![Ds / 16 % 8, Bd16 / 2, Gs, Ds / 128], m![Ds % 16]>()
        .commit_trim::<m![Ds % 16]>()
        .commit();
    let q_dm: DmTensor<bf16, Chip, Cl, HKb, m![Ds / 16 % 8, Bc8, Gs, Ds / 128, Ds % 16]> = unsafe { q_dm.reshape() };
    let q_trf: TrfTensor<bf16, Chip, Cl, HKb, m![Gs], m![Bc8, Ds]> = device
        .sub
        .begin(q_dm.view())
        .fetch::<m![Gs, Bc8, Ds / 128, Ds / 16 % 8], m![Ds % 16]>()
        .collect::<m![Gs, Bc8, Ds / 128, Ds / 16 % 8], m![Ds % 16]>()
        .to_trf();

    // ---- additive key penalty [Bc8, Sk] per slice (0 = key may be visible, MASK_PEN = never visible: unwritten / stale ring row) ----
    let mask_dm: DmTensor<bf16, Chip, Cl, HKb, m![Bd16 / 2, Tx / 32]> = mask.to_dm(&mut device.tdma);
    let mask_dm: DmTensor<bf16, Chip, Cl, HKb, m![Bc8, Sk]> = unsafe { mask_dm.reshape() };
    let mask_vrf: VrfTensor<f32, Chip, Cl, HKb, m![Bc8, Sk]> = device
        .sub
        .begin(mask_dm.view())
        .fetch::<m![1], m![Bc8, Sk]>()
        .fetch_cast::<f32>()
        .collect::<m![Bc8, Sk / 8], m![Sk % 8]>()
        .to_vrf();

    // ---- keys of the B rings: slice (head, lane), element (row, slot, d); streamed through the contraction ----
    let k_raw: DmTensor<bf16, Chip, Cl, HKb, m![Bd16 / 2, Tx / 32, Ds]> = k_cache.dma_gather_scaled(index);
    let k_dm: DmTensor<bf16, Chip, Cl, HKb, m![Bc8, Sk, Ds]> = unsafe { k_raw.reshape() };
    let s: DmTensor<bf16, Chip, Cl, HKb, m![Bc8, Sk, Gs # 8]> = device
        .main
        .begin(k_dm.view())
        .fetch::<m![Bc8, Ds / 32, Sk, Ds / 16 % 2], m![Ds % 16]>()
        .collect::<m![Bc8, Ds / 32, Sk, Ds / 16 % 2], m![Ds % 16]>()
        .contract_outer::<m![Bc8, Ds / 32, Sk], m![Ds % 32], _, _, _>(&q_trf)
        .contract_packet::<m![1]>()
        .contract_time::<m![Bc8, Sk]>()
        .contract_lane::<m![Bc8, Sk], m![Gs # 8]>(LaneMode::Interleaved)
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_clip(ClipBinaryOpF32::Add, &mask_vrf)
        .vector_final()
        .cast::<bf16, m![Gs # 16]>()
        .commit_trim::<m![Gs # 8]>()
        .commit();

    // ---- row max over the key slots that can be visible (penalised slots are far below) ---- (all-reduce Max over the 32 key lanes); packet = query group ----
    let m_dm: DmTensor<f32, Chip, Cl, HX, m![Bc8, Gs # 8]> = device
        .main
        .begin(s.view())
        .fetch::<m![Bc8, Sk], m![Gs # 8]>()
        .fetch_cast::<f32>()
        .collect::<m![Bc8, Sk], m![Gs # 8]>()
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_trim::<m![Gs # 4]>()
        .vector_intra_slice_reduce::<Sk, m![Bc8], m![Gs # 4]>(IntraSliceReduceOpF32::Max)
        .vector_widen_pad::<m![Gs # 8]>()
        .vector_inter_slice_reduce::<HX, m![Bc8]>(InterSliceReduceOpF32::Max)
        .vector_final()
        .commit_trim::<m![Gs # 8]>()
        .commit();
    let m_dm: DmTensor<f32, Chip, Cl, HKb, m![Bc8, Gs # 8]> = unsafe { m_dm.reshape() };
    let m_vrf: VrfTensor<f32, Chip, Cl, HKb, m![Bc8, Gs # 8]> = device
        .sub
        .begin(m_dm.view())
        .fetch::<m![Bc8], m![Gs # 8]>()
        .collect::<m![Bc8], m![Gs # 8]>()
        .to_vrf();

    // ---- p = bf16(exp(s - max)) (penalised slots underflow to exactly 0) ----
    let p: DmTensor<bf16, Chip, Cl, HKb, m![Bc8, Sk, Gs # 8]> = device
        .main
        .begin(s.view())
        .fetch::<m![Bc8, Sk], m![Gs # 8]>()
        .fetch_cast::<f32>()
        .collect::<m![Bc8, Sk], m![Gs # 8]>()
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_trim::<m![Gs # 4]>()
        .vector_fp_binary(FpBinaryOp::SubF, &m_vrf)
        .vector_fp_unary(FpUnaryOp::Exp)
        .vector_widen_pad::<m![Gs # 8]>()
        .vector_final()
        .cast::<bf16, m![Gs # 16]>()
        .commit_trim::<m![Gs # 8]>()
        .commit();

    // ---- row sum of the (bf16) weights, all-reduced; EPS added once in total ----
    let l_dm: DmTensor<f32, Chip, Cl, HX, m![Bc8, Gs # 8]> = device
        .main
        .begin(p.view())
        .fetch::<m![Bc8, Sk], m![Gs # 8]>()
        .fetch_cast::<f32>()
        .collect::<m![Bc8, Sk], m![Gs # 8]>()
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_trim::<m![Gs # 4]>()
        .vector_intra_slice_reduce::<Sk, m![Bc8], m![Gs # 4]>(IntraSliceReduceOpF32::Add)
        .vector_widen_pad::<m![Gs # 8]>()
        .vector_clip(ClipBinaryOpF32::Add, crate::SOFTMAX_EPS / 32.0)
        .vector_inter_slice_reduce::<HX, m![Bc8]>(InterSliceReduceOpF32::Add)
        .vector_final()
        .commit_trim::<m![Gs # 8]>()
        .commit();
    let l_dm: DmTensor<f32, Chip, Cl, HOne, m![Bc8, Gs # 8]> = unsafe { l_dm.reshape() };

    // ---- PV: p as the (tiny) TRF operand (single lane, element = (row, slot, group)), V streamed ----
    let p_trf: TrfTensor<bf16, Chip, Cl, HKb, m![1], m![Bc8, Sk, Gs # 8]> = device
        .sub
        .begin(p.view())
        .fetch::<m![Bc8, Sk / 2], m![Sk % 2, Gs # 8]>()
        .collect::<m![Bc8, Sk / 2], m![Sk % 2, Gs # 8]>()
        .to_trf();
    let v_raw: DmTensor<bf16, Chip, Cl, HKb, m![Bd16 / 2, Tx / 32, Ds]> = v_cache.dma_gather_scaled(index);
    let v_dm: DmTensor<bf16, Chip, Cl, HKb, m![Bc8, Sk, Ds]> = unsafe { v_raw.reshape() };
    let o: DmTensor<f32, Chip, Cl, HOne, m![Bc8, Ds / 32, Gs, Ds % 32]> = device
        .main
        .begin(v_dm.view())
        .fetch::<m![Bc8, Sk, Ds / 32, Ds / 16 % 2], m![Ds % 16]>()
        .collect::<m![Bc8, Sk, Ds / 32, Ds / 16 % 2], m![Ds % 16]>()
        .contract_outer::<m![Bc8, Sk, Ds / 32, Gs], m![Ds % 32], _, _, _>(&p_trf)
        .contract_packet::<m![Ds % 32]>()
        .contract_time::<m![Bc8, Ds / 32, Gs]>()
        .contract_lane::<m![Bc8, Ds / 32, Gs, Ds / 8 % 4], m![Ds % 8]>(LaneMode::Sequential)
        .vector_init()
        .vector_inter_slice_reduce::<HOne, m![Bc8, Ds / 32, Gs, Ds / 8 % 4]>(InterSliceReduceOpF32::Add)
        .vector_final()
        .commit_trim::<m![Ds % 8]>()
        .commit();

    // ---- divide by the row sum, bf16 out ----
    let l_vrf: VrfTensor<f32, Chip, Cl, HOne, m![Bc8, Gs # 8]> = device
        .sub
        .begin(l_dm.view())
        .fetch::<m![Bc8], m![Gs # 8]>()
        .collect::<m![Bc8], m![Gs # 8]>()
        .to_vrf();
    let res: DmTensor<bf16, Chip, Cl, HOne, m![Bc8, Gs, Ds]> = device
        .main
        .begin(o.view())
        .fetch::<m![Bc8, Gs, Ds / 8], m![Ds % 8]>()
        .collect::<m![Bc8, Gs, Ds / 8], m![Ds % 8]>()
        .vector_init()
        .vector_intra_slice_tag(TagMode::Zero)
        .vector_narrow_split::<m![Bc8, Gs, Ds / 4], m![Ds % 4]>()
        .vector_fp_div(&l_vrf)
        .vector_widen_concat::<m![Bc8, Gs, Ds / 8], m![Ds % 8]>()
        .vector_final()
        .cast::<bf16, m![Ds % 8 # 16]>()
        .commit_trim::<m![Ds % 8]>()
        .commit();
    let res: DmTensor<bf16, Chip, Cl, HOne, m![Bd16 / 2, Gs, Ds]> = unsafe { res.reshape() };
    // last group of 8 rows of unit 1 of the prefill output (rows 120..128), written through the prefill output's own handle
    // the last group of 8 rows of unit 1 of wave 1: the caller passes a tile of the wave-1 output view (the same scratch handle as the prefill store)
    res.view().to_hbm_view(&mut device.tdma, dst);
}
}

pub(crate) use decode::decode_attend16;
pub(crate) use prefill::{prefill_wave0, prefill_wave1_r16};
